import { chromium } from '@playwright/test'
const base = 'http://127.0.0.1:8095'
const browser = await chromium.launch({ executablePath: 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe' })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
await page.route('**://static.figma.com/**', r => r.abort())
await page.route('**/*.woff2', r => r.abort())
await page.goto(base + '/#/pages/inspection/index?kind=pre', { waitUntil: 'domcontentloaded', timeout: 30000 }).catch(e=>console.log('goto:',e.message))
await page.waitForTimeout(2500)
const info = await page.evaluate(() => {
  const sz = sel => { const el=document.querySelector(sel); return el? getComputedStyle(el).fontSize : null }
  // count headers
  const headerTexts = [...document.querySelectorAll('uni-page-head, .app-header, .ref8443-header, [class*=header]')].map(e=>({cls:e.className, t:(e.textContent||'').trim().slice(0,10)})).slice(0,6)
  return {
    fieldBlockLabel: sz('.field-block-label'),
    refInput: sz('.ref-input'),
    toggleBtn: sz('.toggle-btn'),
    counterVal: sz('.counter-val'),
    cardH3: sz('.card-h3'),
    headerTexts
  }
})
console.log(JSON.stringify(info, null, 2))
await browser.close()

